namespace Splash\Local\Objects\ThirdParty;

use Splash\Core\SplashCore as Splash;
use Splash\Local\Local;

/**
 * Dolibarr ThirdParty Codes Fields
 *
 * Customer & Accountancy Codes are identifiers, not names.
 */
trait CodesTrait
{
    /**
     * Max Length of Dolibarr Accountancy Codes (llx_societe.code_compta)
     *
     * @var int
     */
    private static int $accountancyCodeMaxLength = 24;

    /**
     * Build Codes Fields using FieldFactory
     *
     * @return void
     */
    protected function buildCodesFields(): void
    {
        global $conf, $langs;

        //====================================================================//
        // Customer Code
        $this->fieldsFactory()->create(SPL_T_VARCHAR)
            ->identifier("code_client")
            ->name($langs->trans("CustomerCode"))
            ->description($langs->trans("CustomerCodeDesc"))
            ->microData("http://schema.org/Organization", "identifier")
            ->addOption('maxLength', "24")
            ->setPreferRead()
            ->isListed()
            ->isIndexed()
        ;
        //====================================================================//
        // Set as Read Only when Auto-Generated by Dolibarr
        if ("mod_codeproduct_leopard" != $conf->global->SOCIETE_CODECLIENT_ADDON) {
            $this->fieldsFactory()->isReadOnly();
        }
        //====================================================================//
        // Customer Accountancy Code
        // Always Read Only: Dolibarr only stores the Accountancy Code for
        // customers, and computes it whenever the Panicum addon is not used
        $this->fieldsFactory()->create(SPL_T_VARCHAR)
            ->identifier("code_compta_client")
            ->name($langs->trans("AccountancyCode"))
            ->microData("http://schema.org/Organization", "fiscalIdentifier")
            ->addOption('maxLength', "24")
            ->isReadOnly()
        ;
    }

    /**
     * Read requested Field
     *
     * @param string $key       Input List Key
     * @param string $fieldName Field Identifier / Name
     *
     * @return void
     */
    protected function getCodesFields(string $key, string $fieldName): void
    {
        //====================================================================//
        // READ Fields
        switch ($fieldName) {
            //====================================================================//
            // Direct Readings
            // Codes may be unset on Dolibarr side: expose an empty string, not null
            case 'code_client':
            case 'code_compta_client':
                $this->getSimple($fieldName, "object", "");

                break;
            default:
                return;
        }

        unset($this->in[$key]);
    }

    /**
     * Write Given Fields
     *
     * @param string      $fieldName Field Identifier / Name
     * @param null|string $fieldData Field Data
     *
     * @return void
     */
    protected function setCodesFields(string $fieldName, ?string $fieldData): void
    {
        //====================================================================//
        // WRITE Field
        switch ($fieldName) {
            //====================================================================//
            // Direct Writings
            case 'code_client':
                $this->setSimple($fieldName, $fieldData);

                break;
            default:
                return;
        }

        unset($this->in[$fieldName]);
    }

    /**
     * Ensure Customer Accountancy Code is Unique, when Required by Dolibarr Setup
     *
     * Accountancy code generators (i.e. Aquarium) may compute a code already used
     * by another third party: Dolibarr stores it on creation without any check,
     * then refuses every later update. A numeric suffix is added to make it unique.
     *
     * @return void
     */
    private function ensureUniqueCustomerAccountancyCode(): void
    {
        //====================================================================//
        // Uniqueness Not Required by Dolibarr Setup
        if (empty(Local::getParameter("SOCIETE_ACCOUNTANCY_CODE_CUSTOMER_UNIQUE"))) {
            return;
        }
        //====================================================================//
        // Not a Customer or No Accountancy Code
        $code = trim((string) $this->object->code_compta_client);
        if (empty($this->object->client) || empty($code)) {
            return;
        }
        //====================================================================//
        // Accountancy Code is Already Unique
        $objectId = (int) $this->object->id;
        if (!$this->object->id_prof_exists("code_compta", $code, $objectId)) {
            return;
        }
        //====================================================================//
        // Search for First Available Suffixed Code
        for ($index = 1; $index < 1000; $index++) {
            $suffix = (string) $index;
            $newCode = substr($code, 0, self::$accountancyCodeMaxLength - strlen($suffix)).$suffix;
            if ($this->object->id_prof_exists("code_compta", $newCode, $objectId)) {
                continue;
            }
            $this->object->code_compta_client = $newCode;
            //====================================================================//
            // Legacy Property, Read First by Dolibarr <= 20 on Updates
            if (property_exists($this->object, "code_compta")) {
                $this->object->code_compta = $newCode;
            }
            Splash::log()->war(sprintf(
                "Customer Accountancy Code %s already used by another ThirdParty, renamed to %s",
                $code,
                $newCode
            ));

            return;
        }
    }
}
